#include <stdio.h>

void double_all(int a[], int n) {
    for (int i = 0; i < n; i++) {
        a[i] *= 2;
    }
}

int main() {
    int a[] = {1, 2, 3};
    double_all(a, 3);
    for (int i = 0; i < 3; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
